"""Reproduce native width intervals from pinned wcwidth 0.2.14, Unicode 16.0.0."""

import hashlib
import importlib.metadata
from pathlib import Path

import wcwidth
from wcwidth import table_vs16, table_wide, table_zero


def main() -> None:
    assert wcwidth.__version__ == "0.2.14"
    lines = [
        "// Generated by tools/generate_terminal_tables.py; do not edit.",
        "// Unicode 16.0.0 widths from wcwidth 0.2.14; VS16 pairs from Unicode 9.0.0.",
    ]
    distribution = importlib.metadata.distribution("wcwidth")
    licenses = [path for path in distribution.files if Path(path).name == "LICENSE"]
    assert len(licenses) == 1
    lines.extend("// " + line for line in distribution.locate_file(licenses[0]).read_text().splitlines())
    for name, module, values in [
        ("ZERO", table_zero, table_zero.ZERO_WIDTH["16.0.0"]),
        ("WIDE", table_wide, table_wide.WIDE_EASTASIAN["16.0.0"]),
        ("VS16", table_vs16, table_vs16.VS16_NARROW_TO_WIDE["9.0.0"]),
    ]:
        lines.append(
            "// Upstream "
            + Path(module.__file__).name
            + " SHA-256: "
            + hashlib.sha256(Path(module.__file__).read_bytes()).hexdigest()
        )
        lines.append("pub const " + name + ": &[(u32, u32)] = &[")
        lines.extend(f"    (0x{start:x}, 0x{end:x})," for start, end in values)
        lines.append("];\n")
    path = Path(__file__).resolve().parents[1] / "py2rust/compiler/service_runtime/src/terminal_tables.rs"
    path.write_text("\n".join(lines))
    return  # noqa: PLR1711 - explicit tool return


if __name__ == "__main__":
    main()
